module multi_pipe_8bit(
    input clk,
    input rst_n,
    input mul_en_in,
    input [7:0] mul_a,
    input [7:0] mul_b,
    output mul_en_out,
    output [15:0] mul_out
);

    reg [2:0] mul_en_out_reg;
    reg [7:0] mul_a_reg;
    reg [7:0] mul_b_reg;
    wire [15:0] temp [7:0];
    reg [15:0] sum [7:0];
    reg [15:0] mul_out_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            mul_en_out_reg <= 3'b0;
        end else begin
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
        end
    end

    assign mul_en_out = mul_en_out_reg[2];

    always @(posedge clk) begin
        if (!rst_n) begin
            mul_a_reg <= 8'b0;
            mul_b_reg <= 8'b0;
        end else if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
    end

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin
            assign temp[i] = mul_b_reg[i] ? {8'b0, mul_a_reg} << i : 16'b0;
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            for (int i = 0; i < 8; i = i + 1) begin
                sum[i] <= 16'b0;
            end
        end else begin
            sum[0] <= temp[0];
            for (int i = 1; i < 8; i = i + 1) begin
                sum[i] <= sum[i-1] + temp[i];
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            mul_out_reg <= 16'b0;
        end else begin
            mul_out_reg <= sum[7];
        end
    end

    assign mul_out = mul_en_out_reg[2] ? mul_out_reg : 16'b0;

endmodule
